        else if (strcmp(argv[i], "-b") == 0 || strcmp(argv[i], "--bits") == 0) { if (i+1 < argc) out_bits = atoi(argv[++i]); }
        else if (strcmp(argv[i], "-r") == 0 || strcmp(argv[i], "--rate") == 0) { if (i+1 < argc) out_rate = atoi(argv[++i]); }
        else if (strcmp(argv[i], "synth") == 0) {
            if (i + 1 < argc) synth_duration = atof(argv[++i]);
            if (i + 2 < argc && strcmp(argv[i+1], "sin") == 0) { i += 2; synth_freq = atof(argv[i]); }
            break;
        } else { outfile = argv[i]; }
        i++;
    }
    if (!outfile) {
        sox_fail("sox", "No input filenames specified");
        printf("\n%s:      SoX v14.4.2\n\nUsage summary: [gopts] [[fopts] infile]... [fopts] outfile [effect [effopt]]...\n", argv[0]);
        return 1;
    }
    uint64_t num_samples = (uint64_t)(synth_duration * out_rate);
    FILE *f = fopen(outfile, "wb");
    if (!f) { sox_fail("formats", "can't open output file `%s': %s", outfile, strerror(errno)); return 2; }
    uint32_t data_size = num_samples * (out_bits / 8);
    fwrite("RIFF", 1, 4, f);
    uint32_t total_size = 36 + data_size;
    fwrite(&total_size, 4, 1, f);
    fwrite("WAVE", 1, 4, f);
    fwrite("fmt ", 1, 4, f);
    uint32_t fmt_size = 16;
    fwrite(&fmt_size, 4, 1, f);
    uint16_t format_tag = 1; fwrite(&format_tag, 2, 1, f);
    uint16_t channels = 1; fwrite(&channels, 2, 1, f);
    fwrite(&out_rate, 4, 1, f);
    uint32_t bytes_per_sec = out_rate * channels * (out_bits / 8);
    fwrite(&bytes_per_sec, 4, 1, f);
    uint16_t block_align = channels * (out_bits / 8);
    fwrite(&block_align, 2, 1, f);
    fwrite(&out_bits, 2, 1, f);
    fwrite("data", 1, 4, f);
    fwrite(&data_size, 4, 1, f);
    for (uint64_t s = 0; s < num_samples; s++) {
        double t = (double)s / out_rate;
        double val = sin(2.0 * M_PI * synth_freq * t);
        if (out_bits == 32) { int32_t ival = (int32_t)(val * 2147483647.0); fwrite(&ival, 4, 1, f); }
        else if (out_bits == 16) { int16_t ival = (int16_t)(val * 32767.0); fwrite(&ival, 2, 1, f); }
        else if (out_bits == 8) { uint8_t ival = (uint8_t)((val + 1.0) * 127.5); fwrite(&ival, 1, 1, f); }
    }
    fclose(f);
    return 0;
}
