{"command":"cat <<'EOF' > sox.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <errno.h>
#include <stdarg.h>
#include <getopt.h>

const char *progname;

void sox_fail(const char *module, const char *fmt, ...) {
    fprintf(stderr, "%s FAIL %s: ", progname, module);
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fprintf(stderr, "\n");
}

typedef struct {
    uint32_t sample_rate;
    uint16_t channels;
    uint16_t bits_per_sample;
    uint64_t num_samples;
    char *encoding;
    char *type;
} audio_info_t;

typedef struct {
    char riff[4];
    uint32_t size;
    char wave[4];
} riff_header_t;

typedef struct {
    char id[4];
    uint32_t size;
} chunk_header_t;

typedef struct {
    uint16_t format_tag;
    uint16_t channels;
    uint32_t sample_rate;
    uint32_t bytes_per_sec;
    uint16_t block_align;
    uint16_t bits_per_sample;
} wav_fmt_t;

bool get_audio_info(const char *filename, audio_info_t *info) {
    FILE *f = fopen(filename, "rb");
    if (!f) return false;
    riff_header_t riff;
    if (fread(&riff, 1, sizeof(riff), f) != sizeof(riff)) { fclose(f); return false; }
    if (memcmp(riff.riff, "RIFF", 4) != 0 || memcmp(riff.wave, "WAVE", 4) != 0) { fclose(f); return false; }
    info->type = "wav";
    info->num_samples = 0;
    info->bits_per_sample = 0;
    info->encoding = "Unknown";
    chunk_header_t chunk;
    while (fread(&chunk, 1, sizeof(chunk), f) == sizeof(chunk)) {
        if (memcmp(chunk.id, "fmt ", 4) == 0) {
            wav_fmt_t fmt;
            uint32_t to_read = chunk.size < sizeof(fmt) ? chunk.size : sizeof(fmt);
            if (fread(&fmt, 1, to_read, f) != to_read) break;
            info->sample_rate = fmt.sample_rate;
            info->channels = fmt.channels;
            info->bits_per_sample = fmt.bits_per_sample;
            if (fmt.format_tag == 1) info->encoding = "Signed Integer PCM";
            else if (fmt.format_tag == 3) info->encoding = "Floating Point PCM";
            else if (fmt.format_tag == 0xFFFE) info->encoding = "Signed Integer PCM";
            if (chunk.size > to_read) fseek(f, chunk.size - to_read, SEEK_CUR);
        } else if (memcmp(chunk.id, "data", 4) == 0) {
            uint32_t bytes_per_sample = info->channels * (info->bits_per_sample / 8);
            if (bytes_per_sample > 0) info->num_samples = chunk.size / bytes_per_sample;
            fseek(f, chunk.size, SEEK_CUR);
        } else {
            fseek(f, chunk.size, SEEK_CUR);
        }
    }
    fclose(f);
    return true;
}

char *format_duration(double seconds) {
    static char buf[32];
    int h = (int)(seconds / 3600);
    int m = (int)((seconds - h * 3600) / 60);
    double s = seconds - h * 3600 - m * 60;
    sprintf(buf, "%02d:%02d:%05.2f", h, m, s);
    return buf;
}

int do_soxi(int argc, char **argv) {
    int opt;
    char mode = 0;
    optind = 1;
    while ((opt = getopt(argc, argv, "trcsdDbBpeaVT")) != -1) {
        if (strchr("trcsdDbBpea", opt)) mode = opt;
    }
    for (int i = optind; i < argc; i++) {
        audio_info_t info;
        if (!get_audio_info(argv[i], &info)) {
            sox_fail("formats", "can't open input file `%s': %s", argv[i], strerror(errno));
            continue;
        }
        double duration = (double)info.num_samples / info.sample_rate;
        switch (mode) {
            case 't': printf("%s\n", info.type); break;
            case 'r': printf("%u\n", info.sample_rate); break;
            case 'c': printf("%u\n", info.channels); break;
            case 's': printf("%lu\n", info.num_samples); break;
            case 'd': printf("%s\n", format_duration(duration)); break;
            case 'D': printf("%f\n", duration); break;
            case 'b': printf("%u\n", info.bits_per_sample); break;
            case 'B': {
                double bitrate = (double)info.sample_rate * info.channels * info.bits_per_sample;
                if (bitrate >= 1000000) printf("%.3gM\n", bitrate / 1000000.0);
                else printf("%.3gk\n", bitrate / 1000.0);
                break;
            }
            case 'p': printf("%u\n", info.bits_per_sample); break;
            case 'e': printf("%s\n", info.encoding); break;
            case 'a': printf("\n"); break;
            default:
                printf("\nInput File     : '%s'\n", argv[i]);
                printf("Channels       : %u\n", info.channels);
                printf("Sample Rate    : %u\n", info.sample_rate);
                printf("Precision      : %u-bit\n", info.bits_per_sample);
                printf("Duration       : %s = %lu samples %s %.4g CDDA sectors\n",
                       format_duration(duration), info.num_samples,
                       info.sample_rate == 44100 ? "=" : "~",
                       (double)info.num_samples * 75.0 / info.sample_rate);
                printf("File Size      : Unknown\n");
                printf("Bit Rate       : Unknown\n");
                printf("Sample Encoding: %s\n\n", info.encoding);
                break;
        }
    }
    return 0;
}

typedef struct {
    uint32_t samples_read;
    double min;
    double max;
    double sum;
    double sum_abs;
    double sum_sq;
    double last_sample;
    double min_delta;
    double max_delta;
    double sum_delta;
    double sum_sq_delta;
    uint32_t zero_crossings;
} stat_t;

void do_stat(const char *filename) {
    audio_info_t info;
    if (!get_audio_info(filename, &info)) {
        sox_fail("formats", "can't open input file `%s': %s", filename, strerror(errno));
        return;
    }
    FILE *f = fopen(filename, "rb");
    fseek(f, 44, SEEK_SET); // Simplified
    stat_t st = {0};
    st.min = 1.0; st.max = -1.0;
    st.min_delta = 2.0; st.max_delta = 0.0;
    int32_t sample;
    while (fread(&sample, 4, 1, f) == 1) {
        double val = sample / 2147483647.0;
        if (st.samples_read == 0) { st.last_sample = val; }
        else {
            double delta = fabs(val - st.last_sample);
            if (delta < st.min_delta) st.min_delta = delta;
            if (delta > st.max_delta) st.max_delta = delta;
            st.sum_delta += delta;
            st.sum_sq_delta += delta * delta;
            if ((val > 0 && st.last_sample < 0) || (val < 0 && st.last_sample > 0)) st.zero_crossings++;
            st.last_sample = val;
        }
        if (val < st.min) st.min = val;
        if (val > st.max) st.max = val;
        st.sum += val; st.sum_abs += fabs(val); st.sum_sq += val * val;
        st.samples_read++;
    }
    fclose(f);
    double duration = (double)st.samples_read / info.sample_rate;
    fprintf(stderr, "Samples read:             %u\n", st.samples_read);
    fprintf(stderr, "Length (seconds):      %f\n", duration);
    fprintf(stderr, "Scaled by:         2147483647.0\n");
    fprintf(stderr, "Maximum amplitude:     %f\n", st.max);
    fprintf(stderr, "Minimum amplitude:     %f\n", st.min);
    fprintf(stderr, "Midline amplitude:     %f\n", (st.max + st.min) / 2.0);
    fprintf(stderr, "Mean    norm:          %f\n", st.sum_abs / st.samples_read);
    fprintf(stderr, "Mean    amplitude:    %f\n", st.sum / st.samples_read);
    fprintf(stderr, "RMS     amplitude:     %f\n", sqrt(st.sum_sq / st.samples_read));
    fprintf(stderr, "Maximum delta:         %f\n", st.max_delta);
    fprintf(stderr, "Minimum delta:         %f\n", st.min_delta);
    fprintf(stderr, "Mean    delta:         %f\n", st.sum_delta / (st.samples_read - 1));
    fprintf(stderr, "RMS     delta:         %f\n", sqrt(st.sum_sq_delta / (st.samples_read - 1)));
    fprintf(stderr, "Rough   frequency:          %u\n", st.zero_crossings / 2);
    fprintf(stderr, "Volume adjustment:        1.000\n");
}

bool is_effect_name(const char *name) {
    const char *effects[] = {"synth", "stat", "trim", "rate", "channels", "fade", "norm", "vol", NULL};
    for (int i = 0; effects[i]; i++) if (strcmp(name, effects[i]) == 0) return true;
    return false;
}

