    if (p) progname = p + 1;
    if (strcmp(progname, "soxi") == 0) return do_soxi(argc, argv);
    if (argc > 1) {
        if (strcmp(argv[1], "--version") == 0) { printf("%s:      SoX v14.4.2\n", argv[0]); return 0; }
        if (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0) {
            printf("%s:      SoX v14.4.2\n\nUsage summary: [gopts] [[fopts] infile]... [fopts] outfile [effect [effopt]]...\n", argv[0]);
            return 0;
        }
        if (strcmp(argv[1], "--info") == 0 || strcmp(argv[1], "--i") == 0) {
            argv[1] = "-i";
            return do_soxi(argc, argv);
        }
    }
    int first_effect_idx = argc;
    for (int i = 1; i < argc; i++) {
        if (is_effect_name(argv[i])) { first_effect_idx = i; break; }
