    if (memcmp(riff.riff, "RIFF", 4) != 0 || memcmp(riff.wave, "WAVE", 4) != 0) { fclose(f); return false; }
    info->type = "wav";
    info->num_samples = 0;
    info->bits_per_sample = 0;
    info->encoding = "Unknown";
    chunk_header_t chunk;
    while (fread(&chunk, 1, sizeof(chunk), f) == sizeof(chunk)) {
        if (memcmp(chunk.id, "fmt ", 4) == 0) {
            wav_fmt_t fmt;
            uint32_t to_read = chunk.size < sizeof(fmt) ? chunk.size : sizeof(fmt);
            if (fread(&fmt, 1, to_read, f) != to_read) break;
            info->sample_rate = fmt.sample_rate;
            info->channels = fmt.channels;
            info->bits_per_sample = fmt.bits_per_sample;
