    double last_sample; double min_delta; double max_delta; double sum_delta; double sum_sq_delta;
    uint32_t zero_crossings;
} stat_t;

void do_stat(const char *filename) {
    audio_info_t info; if (!get_audio_info(filename, &info)) { sox_fail("formats", "can't open input file `%s': %s", filename, strerror(errno)); return; }
    FILE *f = fopen(filename, "rb"); riff_header_t riff; fread(&riff, 1, sizeof(riff), f);
    chunk_header_t chunk; while (fread(&chunk, 1, sizeof(chunk), f) == sizeof(chunk)) { if (memcmp(chunk.id, "data", 4) == 0) break; fseek(f, chunk.size, SEEK_CUR); }
    stat_t st = {0}; st.min = 1.0; st.max = -1.0; st.min_delta = 2.0; st.max_delta = 0.0;
    for (uint64_t i = 0; i < info.num_samples * info.channels; i++) {
        double val = 0;
        if (info.bits_per_sample == 32) { int32_t s; fread(&s, 4, 1, f); val = s / 2147483647.0; }
        else if (info.bits_per_sample == 16) { int16_t s; fread(&s, 2, 1, f); val = s / 32767.0; }
        else if (info.bits_per_sample == 8) { uint8_t s; fread(&s, 1, 1, f); val = (s - 128) / 127.0; }
        if (st.samples_read == 0) { st.last_sample = val; }
        else {
            double delta = fabs(val - st.last_sample);
            if (delta < st.min_delta) st.min_delta = delta; if (delta > st.max_delta) st.max_delta = delta;
            st.sum_delta += delta; st.sum_sq_delta += delta * delta;
            if ((val > 0 && st.last_sample < 0) || (val < 0 && st.last_sample > 0)) st.zero_crossings++;
            st.last_sample = val;
        }
        if (val < st.min) st.min = val; if (val > st.max) st.max = val;
        st.sum += val; st.sum_abs += fabs(val); st.sum_sq += val * val; st.samples_read++;
    }
    fclose(f); double duration = (double)st.samples_read / (info.sample_rate * info.channels);
    fprintf(stderr, "Samples read:             %u\n", st.samples_read / info.channels);
    fprintf(stderr, "Length (seconds):      %f\n", duration); fprintf(stderr, "Scaled by:         2147483647.0\n");
    fprintf(stderr, "Maximum amplitude:     %f\n", st.max); fprintf(stderr, "Minimum amplitude:     %f\n", st.min);
    fprintf(stderr, "Midline amplitude:     %f\n", (st.max + st.min) / 2.0); fprintf(stderr, "Mean    norm:          %f\n", st.sum_abs / st.samples_read);
    fprintf(stderr, "Mean    amplitude:    %f\n", st.sum / st.samples_read); fprintf(stderr, "RMS     amplitude:     %f\n", sqrt(st.sum_sq / st.samples_read));
    fprintf(stderr, "Maximum delta:         %f\n", st.max_delta); fprintf(stderr, "Minimum delta:         %f\n", st.min_delta);
    fprintf(stderr, "Mean    delta:         %f\n", st.sum_delta / (st.samples_read - 1));
    fprintf(stderr, "RMS     delta:         %f\n", sqrt(st.sum_sq_delta / (st.samples_read - 1)));
    fprintf(stderr, "Rough   frequency:          %u\n", st.zero_crossings / (2 * info.channels));
    fprintf(stderr, "Volume adjustment:        1.000\n");
}

