    if (memcmp(riff.riff, "RIFF", 4) != 0 || memcmp(riff.wave, "WAVE", 4) != 0) { fclose(f); return false; }
    info->type = "wav"; info->num_samples = 0; info->bits_per_sample = 0; info->encoding = "Unknown";
